const input = $input.first().json || {};

function compactJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    return String(value);
  }
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C4-B",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        extraction: null,
        c2f_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-B will not extract fields when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "extract_fields") {
  return fail({
    code: "EXTRACTION_NOT_REQUESTED",
    message: "source.next_action is not extract_fields.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.extraction_goal) {
  return fail({
    code: "MISSING_EXTRACTION_GOAL",
    message: "config.extraction_goal is required."
  });
}

if (!config.client_ai_profile || typeof config.client_ai_profile !== "object") {
  return fail({
    code: "MISSING_CLIENT_AI_PROFILE",
    message: "config.client_ai_profile is required."
  });
}

if (!config.client_ai_profile.client_profile || !config.client_ai_profile.extraction_rules) {
  return fail({
    code: "INCOMPLETE_CLIENT_AI_PROFILE",
    message: "client_ai_profile must include at least client_profile and extraction_rules."
  });
}

const extractionRules = config.client_ai_profile.extraction_rules || {};

if (!Array.isArray(extractionRules.required_fields)) {
  return fail({
    code: "MISSING_REQUIRED_FIELDS",
    message: "client_ai_profile.extraction_rules.required_fields must be an array."
  });
}

if (!config.llm || typeof config.llm !== "object") {
  return fail({
    code: "MISSING_LLM_CONFIG",
    message: "config.llm is required."
  });
}

if (!config.llm.provider || !config.llm.endpoint || !config.llm.model) {
  return fail({
    code: "INCOMPLETE_LLM_CONFIG",
    message: "config.llm must include provider, endpoint, and model."
  });
}

if (config.llm.provider !== "groq") {
  return fail({
    code: "UNSUPPORTED_LLM_PROVIDER",
    message: "C4-B v1 demo supports provider = groq.",
    details: [{ provider: config.llm.provider }]
  });
}

const rawText =
  source.payload?.raw_text ||
  source.payload?.message ||
  source.payload?.text ||
  "";

if (!rawText || !String(rawText).trim()) {
  return fail({
    code: "MISSING_RAW_TEXT",
    message: "source.payload.raw_text, message, or text is required."
  });
}

const profile = config.client_ai_profile;

const systemInstruction = [
  "You are a client-configured AI extraction component inside an automation workflow.",
  "You extract structured fields from messy text using only the provided raw text and extraction rules.",
  "You do not classify the input. You do not qualify the lead. You do not draft messages. You do not execute tools.",
  "Do not invent missing fields.",
  "If a field is missing, return null for that field and list it in missing_required_fields if required.",
  "If confidence is low or a required field is missing, set manual_review_required true.",
  "Return valid JSON only. Do not include markdown fences."
].join(" ");

const requiredFields = extractionRules.required_fields || [];
const optionalFields = extractionRules.optional_fields || [];
const allFields = [...new Set([...requiredFields, ...optionalFields])];

const outputSchema = {
  extraction: {
    extracted_fields: Object.fromEntries(allFields.map(field => [field, "string | number | boolean | null"])),
    field_confidence: Object.fromEntries(allFields.map(field => [field, "number from 0 to 1"])),
    missing_required_fields: ["string"],
    low_confidence_fields: ["string"],
    assumptions: ["string"],
    risk_flags: ["string"],
    manual_review_required: "boolean",
    recommended_next_action: "validate_payload | manual_review"
  }
};

const userContent = [
  "EXTRACTION TASK",
  compactJson({
    extraction_mode: config.extraction_mode || "rules_plus_ai",
    extraction_goal: config.extraction_goal,
    default_next_action: config.default_next_action || "validate_payload"
  }),
  "",
  "RAW TEXT",
  String(rawText),
  "",
  "SOURCE PAYLOAD",
  compactJson(source.payload || {}),
  "",
  "UPSTREAM CONTEXT",
  compactJson({
    source_component: source.component_id || null,
    classification: source.classification || null,
    metadata: source.metadata || null
  }),
  "",
  "CLIENT AI PROFILE",
  compactJson(profile),
  "",
  "EXTRACTION RULES TO ENFORCE",
  compactJson({
    required_fields: requiredFields,
    optional_fields: optionalFields,
    missing_required_field_action: extractionRules.missing_required_field_action || "manual_review",
    allow_inference: extractionRules.allow_inference === true,
    never_infer_fields: extractionRules.never_infer_fields || [],
    low_confidence_action: extractionRules.low_confidence_action || "manual_review",
    manual_review_confidence_threshold: extractionRules.manual_review_confidence_threshold ?? 0.75,
    risk_manual_review_triggers: profile.risk_boundaries?.manual_review_triggers || []
  }),
  "",
  "DECISION RULES",
  compactJson({
    no_invention_rule: "Do not invent missing fields. Return null if absent.",
    no_classification_rule: "Do not classify the message. Only extract fields.",
    required_missing_rule: "If any required field is missing/null/empty, include it in missing_required_fields and set manual_review_required true.",
    low_confidence_rule: "If any field confidence is below threshold, include it in low_confidence_fields.",
    recommended_next_action_rule: "Use validate_payload only if no required fields are missing and manual_review_required is false. Otherwise use manual_review."
  }),
  "",
  "OUTPUT JSON SCHEMA",
  compactJson(outputSchema),
  "",
  "Return JSON only with the key extraction."
].join("\n");

const body = {
  model: config.llm.model,
  messages: [
    {
      role: "system",
      content: systemInstruction
    },
    {
      role: "user",
      content: userContent
    }
  ],
  temperature: config.llm.temperature ?? 0.1,
  max_tokens: config.llm.max_tokens ?? 800,
  response_format: {
    type: "json_object"
  }
};

return [
  {
    json: {
      stop_before_http: false,
      request: {
        provider: config.llm.provider,
        endpoint: config.llm.endpoint,
        body
      },
      context: {
        component_id: "C4-B",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        extraction_mode: config.extraction_mode || "rules_plus_ai",
        extraction_goal: config.extraction_goal,
        client_ai_profile: profile,
        extraction_rules: extractionRules,
        source_result: source,
        default_next_action: config.default_next_action || "validate_payload"
      }
    }
  }
];

const llmOutput = $input.first().json || {};
const prepared = $("Prepare Extraction Request").first().json;
const context = prepared.context;

const content =
  llmOutput.choices?.[0]?.message?.content ??
  llmOutput.choices?.[0]?.text ??
  null;

let parsedJson = null;
let parseError = null;

if (content) {
  try {
    parsedJson = JSON.parse(content);
  } catch (error) {
    parseError = error.message;
  }
}

const extraction = parsedJson?.extraction || null;

if (!extraction) {
  return [
    {
      json: {
        success: false,
        component_id: context.component_id,
        component_version: context.component_version,
        event_id: context.event_id,
        event_type: context.event_type,
        extraction: null,
        c2f_handoff: null,
        manual_review_handoff: null,
        source_result: context.source_result,
        error: {
          code: parseError ? "EXTRACTION_PARSE_FAILED" : "MISSING_EXTRACTION",
          message: parseError
            ? "LLM response could not be parsed as JSON."
            : "LLM response did not include extraction.",
          details: [{ raw_content: content, parse_error: parseError }]
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

const requiredFields = context.extraction_rules.required_fields || [];
const threshold = Number(context.extraction_rules.manual_review_confidence_threshold ?? 0.75);
const extractedFields = extraction.extracted_fields || {};
const fieldConfidence = extraction.field_confidence || {};

const missingRequiredFields = Array.isArray(extraction.missing_required_fields)
  ? extraction.missing_required_fields
  : requiredFields.filter(field => {
      const value = extractedFields[field];
      return value === undefined || value === null || String(value).trim() === "";
    });

const lowConfidenceFields = Array.isArray(extraction.low_confidence_fields)
  ? extraction.low_confidence_fields
  : Object.entries(fieldConfidence)
      .filter(([field, score]) => Number(score) < threshold)
      .map(([field]) => field);

const manualReviewRequired =
  extraction.manual_review_required === true ||
  missingRequiredFields.length > 0 ||
  lowConfidenceFields.length > 0;

const recommendedNextAction = manualReviewRequired
  ? "manual_review"
  : extraction.recommended_next_action || context.default_next_action || "validate_payload";

const normalizedExtraction = {
  extracted_fields: extractedFields,
  field_confidence: fieldConfidence,
  missing_required_fields: missingRequiredFields,
  low_confidence_fields: lowConfidenceFields,
  assumptions: Array.isArray(extraction.assumptions) ? extraction.assumptions : [],
  risk_flags: Array.isArray(extraction.risk_flags) ? extraction.risk_flags : [],
  manual_review_required: manualReviewRequired,
  recommended_next_action: recommendedNextAction,
  provider: prepared.request.provider,
  model: prepared.request.body.model,
  usage: llmOutput.usage || null,
  finish_reason: llmOutput.choices?.[0]?.finish_reason || null
};

let c2fHandoff = null;
let manualReviewHandoff = null;
let nextAction = recommendedNextAction;

if (manualReviewRequired || recommendedNextAction === "manual_review") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C4-B",
      component_version: "v1",
      event_id: context.event_id,
      event_type: context.event_type,
      extraction: normalizedExtraction,
      source_result: context.source_result,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "extraction_review",
      review_reason: "Extraction requires manual review",
      reviewer_email: context.client_ai_profile?.approval_rules?.primary_reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "ops",
      priority: missingRequiredFields.length ? "high" : "normal",
      allowed_actions: ["confirm_extraction", "edit_fields", "reject_record", "request_more_info"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
} else {
  c2fHandoff = {
    next_component: "C2-F",
    input: {
      success: true,
      component_id: "C4-B",
      component_version: "v1",
      event_id: context.event_id,
      event_type: "extracted_payload",
      payload: extractedFields,
      metadata: {
        source_component: context.source_result.component_id || null,
        original_event_type: context.source_result.event_type || null,
        extracted_at: new Date().toISOString(),
        extraction_goal: context.extraction_goal
      },
      extraction: normalizedExtraction,
      error: null,
      next_action: "validate_payload"
    },
    config: {
      validation_rules: {
        required_fields: requiredFields,
        email_fields: ["email"]
      },
      default_next_action: "dedupe_check"
    }
  };

  nextAction = context.default_next_action || "validate_payload";
}

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      extraction: normalizedExtraction,
      c2f_handoff: c2fHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: context.source_result,
      error: null,
      next_action: nextAction
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      extraction: prepared.extraction,
      c2f_handoff: prepared.c2f_handoff,
      manual_review_handoff: prepared.manual_review_handoff,
      source_result: prepared.source_result,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];
